// Preloaded via `node --import ./preload-env.js build` before the SvelteKit
// server initialises. This ensures process.env is populated from the monorepo
// root .env before adapter-node's server.init() snapshots it into
// $env/dynamic/private. In Docker, env vars are injected directly by
// docker-compose so dotenv is a safe no-op (it won't override existing vars).
import { config } from 'dotenv';
import { resolve } from 'path';

config({ path: resolve(process.cwd(), '../../.env') });

import { env } from '$env/dynamic/private';
import { json } from '@sveltejs/kit';
import type { Handle, HandleServerError } from '@sveltejs/kit';
import { validateDebugToken } from '$lib/server/debug-helpers';

export const handle: Handle = async ({ event, resolve }) => {
  // Debug API auth — gate /api/debug/* behind Bearer token
  if (event.url.pathname.startsWith('/api/debug/')) {
    const auth = event.request.headers.get('authorization');
    if (!validateDebugToken(auth, env.DEBUG_API_TOKEN)) {
      return json({ error: 'Unauthorized' }, { status: 401 });
    }
  }

  const response = await resolve(event);
  if (
    event.request.method === 'GET' &&
    (response.headers.get('content-type') ?? '').includes('text/html')
  ) {
    // If the request carries the recently-viewed cookie the response is personalised,
    // so it must not be stored in a shared cache (CDN). Non-cookied visitors (first-time
    // or cleared) are safe to cache publicly.
    const personalized = event.request.headers.get('cookie')?.includes('rv=') ?? false;
    response.headers.set(
      'Cache-Control',
      personalized
        ? 'private, max-age=0'
        : 'public, max-age=0, s-maxage=30, stale-while-revalidate=60',
    );
  }
  return response;
};

export const handleError: HandleServerError = ({ error, event, status }) => {
  // Log server-side errors with context (avoids leaking stack traces to the client)
  const message = error instanceof Error ? error.message : 'Unknown error';
  console.error(`[server error] ${status} on ${event.url.pathname}: ${message}`);

  // Return a safe, generic message to the client
  return {
    message: status === 404 ? 'Not found' : 'An unexpected error occurred',
  };
};

import { env } from '$env/dynamic/private';
import { env as publicEnv } from '$env/dynamic/public';
import type { LayoutServerLoad } from './$types';
import { db, airports } from '$lib/server/db';

const AIRPORTS_TTL_MS = 5 * 60 * 1000; // 5 minutes

interface AirportCache {
  data: Record<string, {
    iataCode: string;
    icaoCode: string | null;
    name: string;
    city: string | null;
    latitude: number | null;
    longitude: number | null;
  }>;
  expiresAt: number;
}

let airportsCache: AirportCache | null = null;

async function getCachedAirports(): Promise<AirportCache['data']> {
  if (airportsCache && Date.now() < airportsCache.expiresAt) return airportsCache.data;
  const rows = await db
    .select({
      iataCode: airports.iataCode,
      icaoCode: airports.icaoCode,
      name: airports.name,
      city: airports.city,
      latitude: airports.latitude,
      longitude: airports.longitude,
    })
    .from(airports);
  const data = Object.fromEntries(rows.map(a => [a.iataCode, a]));
  airportsCache = { data, expiresAt: Date.now() + AIRPORTS_TTL_MS };
  return data;
}

export const load: LayoutServerLoad = async (_) => {
  const domain = env.DOMAIN || 'airways.gg';

  const airportsMap = await getCachedAirports();

  return {
    siteUrl: `https://${domain}`,
    buyMeACoffeeUrl: publicEnv.PUBLIC_BUY_ME_A_COFFEE_URL || null,
    umamiWebsiteId: publicEnv.PUBLIC_UMAMI_WEBSITE_ID || null,
    umamiUrl: publicEnv.PUBLIC_UMAMI_URL || null,
    airports: airportsMap,
  };
};

/**
 * Shared helpers for /api/debug/* endpoints.
 * Server-only — never imported client-side.
 */

/**
 * Structured JSON response with metadata.
 * Every debug endpoint wraps its data in this shape.
 */
export function debugResponse(
  rows: unknown[],
  queryMs: number,
): Response {
  return new Response(
    JSON.stringify({
      rows,
      count: rows.length,
      queryMs: Math.round(queryMs),
    }),
    {
      status: 200,
      headers: {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      },
    },
  );
}

/**
 * Error response for client errors (bad params, auth failures).
 */
export function debugError(message: string, status = 400): Response {
  return new Response(
    JSON.stringify({ error: message }),
    {
      status,
      headers: {
        'content-type': 'application/json',
        'cache-control': 'no-store',
      },
    },
  );
}

/**
 * Parse and clamp pagination params from URL search params.
 * Returns { limit, offset } with enforced caps.
 */
export function parsePagination(
  searchParams: URLSearchParams,
  defaults: { defaultLimit?: number; maxLimit?: number } = {},
): { limit: number; offset: number } {
  const defaultLimit = defaults.defaultLimit ?? 100;
  const maxLimit = defaults.maxLimit ?? 1000;

  const rawLimit = parseInt(searchParams.get('limit') ?? '', 10);
  const limit = Math.min(
    Math.max(1, isNaN(rawLimit) ? defaultLimit : rawLimit),
    maxLimit,
  );
  const rawOffset = parseInt(searchParams.get('offset') ?? '', 10);
  const offset = Math.max(0, isNaN(rawOffset) ? 0 : rawOffset);

  return { limit, offset };
}

/** SQL commands allowed by the debug SQL endpoint */
const ALLOWED_COMMANDS = new Set(['SELECT', 'EXPLAIN', 'SHOW', 'DESCRIBE', 'WITH']);

/** Keywords that are blocked even inside otherwise-allowed statements */
const DANGEROUS_KEYWORDS = ['INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE', 'CREATE'];

/**
 * Validate a SQL query string for the debug endpoint.
 * Returns { valid: true } or { valid: false, error: string }.
 */
export function validateSqlQuery(query: string): { valid: true } | { valid: false; error: string } {
  const firstToken = query.split(/\s+/)[0]?.toUpperCase() ?? '';
  if (!ALLOWED_COMMANDS.has(firstToken)) {
    return { valid: false, error: `Statement type "${firstToken}" not allowed. Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH are permitted.` };
  }

  const upperQuery = query.toUpperCase();
  for (const keyword of DANGEROUS_KEYWORDS) {
    if (new RegExp(`\\b${keyword}\\b`).test(upperQuery)) {
      return { valid: false, error: `Dangerous keyword "${keyword}" detected in query. Only read-only statements are allowed.` };
    }
  }

  return { valid: true };
}

/**
 * Validate a Bearer token for the debug API.
 * Returns true if the Authorization header matches the expected token.
 */
export function validateDebugToken(
  authHeader: string | null,
  expectedToken: string | undefined,
): boolean {
  if (!expectedToken || !authHeader) return false;
  return authHeader === `Bearer ${expectedToken}`;
}

import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { debugResponse, debugError, validateSqlQuery } from '$lib/server/debug-helpers';
import { sql } from 'drizzle-orm';

/**
 * POST /api/debug/sql
 * Body: { "sql": "SELECT * FROM flights LIMIT 10" }
 *
 * Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH (CTE) are allowed.
 * All other statements are rejected with 403.
 * Queries have a 30-second timeout via statement_timeout.
 */
export const POST: RequestHandler = async ({ request }) => {
  const t0 = performance.now();
  try {
    const body = await request.json() as { sql?: string };
    const query = body.sql?.trim();

    if (!query) return debugError('Missing "sql" field in request body', 400);

    // Validate query (SELECT-only, no dangerous keywords)
    const validation = validateSqlQuery(query);
    if (!validation.valid) {
      return debugError(validation.error, 403);
    }

    // Get the underlying pg pool for raw SQL execution
    const d = getDb();

    // Set session-level timeout for this query only, then reset
    await d.execute(sql`SET SESSION statement_timeout = '30s'`);

    let result;
    try {
      result = await d.execute(sql`${sql.raw(query)}`);
    } finally {
      await d.execute(sql`RESET statement_timeout`);
    }

    const queryMs = performance.now() - t0;

    // Log query for audit
    const truncated = query.length > 200 ? query.substring(0, 200) + '...' : query;
    console.log(`[debug/sql] ${queryMs}ms | rows=${result.rows.length} | ${truncated}`);

    return debugResponse(result.rows, queryMs);
  } catch (err) {
    const queryMs = performance.now() - t0;
    const message = err instanceof Error ? err.message : 'Query failed';
    console.error(`[debug/sql] ERROR ${queryMs}ms | ${message}`);
    return debugError(message, 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flights } from '$lib/server/db';
import { debugResponse, debugError, parsePagination } from '$lib/server/debug-helpers';
import { eq, gte, lte, and, desc, asc, ilike } from 'drizzle-orm';

/**
 * GET /api/debug/flights
 * Query params: date, status, departure_airport, arrival_airport, flight_number,
 *   airline_code, canceled, aircraft_registration, sort, order, limit, offset
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();

  try {
    const { limit, offset } = parsePagination(url.searchParams);
    const conditions = [];

    // Date filter — matches flight_date
    const dateParam = url.searchParams.get('date');
    if (dateParam) {
      conditions.push(eq(flights.flightDate, dateParam));
    }

    // Date range filter
    const dateFrom = url.searchParams.get('date_from');
    const dateTo = url.searchParams.get('date_to');
    if (dateFrom) conditions.push(gte(flights.flightDate, dateFrom));
    if (dateTo) conditions.push(lte(flights.flightDate, dateTo));

    // Status filter
    const statusParam = url.searchParams.get('status');
    if (statusParam) {
      conditions.push(eq(flights.status, statusParam));
    }

    // Airport filters
    const depAirport = url.searchParams.get('departure_airport');
    if (depAirport) conditions.push(eq(flights.departureAirport, depAirport.toUpperCase()));
    const arrAirport = url.searchParams.get('arrival_airport');
    if (arrAirport) conditions.push(eq(flights.arrivalAirport, arrAirport.toUpperCase()));

    // Flight number — partial match
    const flightNumber = url.searchParams.get('flight_number');
    if (flightNumber) conditions.push(ilike(flights.flightNumber, `%${flightNumber}%`));

    // Airline code
    const airlineCode = url.searchParams.get('airline_code');
    if (airlineCode) conditions.push(eq(flights.airlineCode, airlineCode.toUpperCase()));

    // Canceled flag
    const canceledParam = url.searchParams.get('canceled');
    if (canceledParam !== null) {
      conditions.push(eq(flights.canceled, canceledParam === 'true'));
    }

    // Aircraft registration
    const reg = url.searchParams.get('aircraft_registration');
    if (reg) conditions.push(eq(flights.aircraftRegistration, reg.toUpperCase()));

    // Sorting
    const sortField = url.searchParams.get('sort') ?? 'scheduled_departure';
    const sortOrder = url.searchParams.get('order') === 'asc' ? asc : desc;

    // Map sort field names to Drizzle columns
    const sortColumns: Record<string, typeof flights.scheduledDeparture> = {
      scheduled_departure: flights.scheduledDeparture,
      scheduled_arrival: flights.scheduledArrival,
      actual_departure: flights.actualDeparture,
      actual_arrival: flights.actualArrival,
      delay_minutes: flights.delayMinutes,
      flight_date: flights.flightDate,
      created_at: flights.createdAt,
      updated_at: flights.updatedAt,
    };
    const sortCol = sortColumns[sortField] ?? flights.scheduledDeparture;

    const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

    const rows = conditions.length > 0
      ? await db.select().from(flights).where(whereClause).orderBy(sortOrder(sortCol)).limit(limit).offset(offset)
      : await db.select().from(flights).orderBy(sortOrder(sortCol)).limit(limit).offset(offset);

    const queryMs = performance.now() - t0;
    return debugResponse(rows, queryMs);
  } catch (err) {
    console.error('[debug/flights]', err);
    return debugError('Query failed', 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flights, flightStatusHistory, weatherData, aircraftPositions, flightTimes, airportDaylight } from '$lib/server/db';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import { eq, desc, and, lte, gte, inArray, isNotNull, asc } from 'drizzle-orm';

/**
 * Mirrors the flight detail load function.
 * GET /api/debug/ui/flight/:id
 */
export const GET: RequestHandler = async ({ params }) => {
  const t0 = performance.now();
  try {
    const id = parseInt(params.id, 10);
    if (isNaN(id)) return debugError('Invalid flight ID', 400);

    const [flight] = await db.select().from(flights).where(eq(flights.id, id)).limit(1);
    if (!flight) return debugError('Flight not found', 404);

    const flightTime = flight.scheduledDeparture;
    const windowStart = new Date(flightTime.getTime() - 90 * 60000);
    const windowEnd   = new Date(Math.max(flightTime.getTime() + 90 * 60000, Date.now()));
    const airports    = [...new Set([flight.departureAirport, flight.arrivalAirport])];

    const depDate = flight.scheduledDeparture.toISOString().split('T')[0];
    const arrDate = flight.scheduledArrival.toISOString().split('T')[0];

    const rotationStart = new Date(flight.scheduledDeparture.getTime() - 24 * 60 * 60 * 1000);
    const rotationFlights = flight.aircraftRegistration
      ? await db.select({
          id: flights.id, flightNumber: flights.flightNumber,
          departureAirport: flights.departureAirport, arrivalAirport: flights.arrivalAirport,
          scheduledDeparture: flights.scheduledDeparture, scheduledArrival: flights.scheduledArrival,
          actualDeparture: flights.actualDeparture, actualArrival: flights.actualArrival,
          status: flights.status, canceled: flights.canceled, delayMinutes: flights.delayMinutes,
        })
        .from(flights)
        .where(and(
          eq(flights.aircraftRegistration, flight.aircraftRegistration),
          gte(flights.scheduledDeparture, rotationStart),
          isNotNull(flights.aircraftRegistration),
        ))
        .orderBy(asc(flights.scheduledDeparture))
      : [];

    const [rawStatusHistory, weatherRows, positionRows, times, daylightRows] = await Promise.all([
      db.select().from(flightStatusHistory)
        .where(eq(flightStatusHistory.flightId, id))
        .orderBy(desc(flightStatusHistory.statusTimestamp)),
      db.select().from(weatherData)
        .where(and(
          inArray(weatherData.airportCode, airports),
          gte(weatherData.timestamp, windowStart),
          lte(weatherData.timestamp, windowEnd),
        ))
        .orderBy(desc(weatherData.timestamp)),
      db.select().from(aircraftPositions)
        .where(eq(aircraftPositions.flightId, id))
        .orderBy(desc(aircraftPositions.positionTimestamp))
        .limit(1),
      db.select().from(flightTimes).where(eq(flightTimes.flightId, id)),
      db.select().from(airportDaylight)
        .where(and(
          inArray(airportDaylight.airportCode, airports),
          inArray(airportDaylight.date, [depDate, arrDate]),
        )),
    ]);

    // WeatherMap — most recent past record per airport
    const weatherMap: Record<string, typeof weatherData.$inferSelect> = {};
    const now = new Date();
    for (const row of weatherRows) {
      const existing = weatherMap[row.airportCode];
      const rowTs = new Date(row.timestamp).getTime();
      if (!existing) { weatherMap[row.airportCode] = row; continue; }
      const existingTs = new Date(existing.timestamp).getTime();
      if (rowTs <= now.getTime() && existingTs > now.getTime()) {
        weatherMap[row.airportCode] = row;
      } else if (rowTs <= now.getTime() && existingTs <= now.getTime() && rowTs > existingTs) {
        weatherMap[row.airportCode] = row;
      }
    }

    // Daylight map
    const daylightMap: Record<string, typeof airportDaylight.$inferSelect[]> = {};
    for (const row of daylightRows) {
      if (!daylightMap[row.airportCode]) daylightMap[row.airportCode] = [];
      daylightMap[row.airportCode].push(row);
    }

    // Deduplicate status history
    const latestGuernseyTs = rawStatusHistory
      .find(e => e.source === 'guernsey_airport')
      ?.statusTimestamp ?? null;
    const seenBySource = new Map<string, Set<string>>();
    const statusHistory = rawStatusHistory.filter((entry) => {
      const key = entry.source;
      if (!seenBySource.has(key)) seenBySource.set(key, new Set());
      const seen = seenBySource.get(key)!;
      if (seen.has(entry.statusMessage)) return false;
      seen.add(entry.statusMessage);
      if (
        entry.source === 'fr24' &&
        entry.statusMessage.toLowerCase().startsWith('estimated dep') &&
        latestGuernseyTs !== null &&
        new Date(latestGuernseyTs) >= new Date(entry.statusTimestamp)
      ) return false;
      return true;
    });

    const data = {
      flight,
      statusHistory,
      weatherMap,
      daylightMap,
      position: positionRows[0] ?? null,
      rotationFlights,
      times,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/flight]', err);
    return debugError('Query failed', 500);
  }
};

# Development environment
# Usage: docker compose -f docker-compose.dev.yml --env-file .env.dev up -d

services:
  app:
    build:
      context: .
      dockerfile: apps/web/Dockerfile
    ports:
      - "3000:3000"
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - NODE_ENV=production
      - ADDRESS_HEADER=CF-Connecting-IP
      - BODY_SIZE_LIMIT=10M
      - ML_SERVICE_URL=http://ml-service:8000
      - SESSION_SECRET=${SESSION_SECRET}
      - DOMAIN=${DOMAIN:?DOMAIN is required}
      - ORIGIN=https://${DOMAIN:?DOMAIN is required}
      - PUBLIC_BUY_ME_A_COFFEE_URL=${PUBLIC_BUY_ME_A_COFFEE_URL}
      - PUBLIC_FORMSPREE_URL=${PUBLIC_FORMSPREE_URL}
      - PUBLIC_UMAMI_WEBSITE_ID=${PUBLIC_UMAMI_WEBSITE_ID}
      - PUBLIC_UMAMI_URL=${PUBLIC_UMAMI_URL}
      - PUBLIC_VAPID_PUBLIC_KEY=${PUBLIC_VAPID_PUBLIC_KEY}
      - DEBUG_API_TOKEN=${DEBUG_API_TOKEN}
    labels:
      - 'traefik.enable=true'
      - 'traefik.http.routers.airwaysgg-dev.rule=Host(`${DOMAIN}`)'
      - 'traefik.http.routers.airwaysgg-dev.entrypoints=websecure'
      - 'traefik.http.routers.airwaysgg-dev.tls=true'
      - 'traefik.http.routers.airwaysgg-dev.tls.certresolver=letsencrypt'
      - 'traefik.http.services.airwaysgg-dev.loadbalancer.server.port=3000'
    depends_on:
      - ml-service
    networks:
      - web
    restart: unless-stopped

  notification-service:
    build:
      context: .
      dockerfile: apps/notification-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - VAPID_PUBLIC_KEY=${VAPID_PUBLIC_KEY}
      - VAPID_PRIVATE_KEY=${VAPID_PRIVATE_KEY}
      - VAPID_SUBJECT=${VAPID_SUBJECT}
      - NOTIFY_POLL_INTERVAL_MS=${NOTIFY_POLL_INTERVAL_MS:-15000}
      - NODE_ENV=production
    networks:
      - web
    restart: unless-stopped

  fr24-scraper:
    init: true
    build:
      context: .
      dockerfile: apps/fr24-scraper/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - SCRAPER_CUTOFF_HOUR=${SCRAPER_CUTOFF_HOUR:-23}
      - SCRAPER_WAKE_OFFSET_MINS=${SCRAPER_WAKE_OFFSET_MINS:-30}
      - SCRAPER_INTERVAL_HIGH_MINS=${SCRAPER_INTERVAL_HIGH_MINS:-2}
      - SCRAPER_INTERVAL_MEDIUM_MINS=${SCRAPER_INTERVAL_MEDIUM_MINS:-5}
      - SCRAPER_INTERVAL_LOW_MINS=${SCRAPER_INTERVAL_LOW_MINS:-10}
      - SCRAPER_INTERVAL_IDLE_MINS=${SCRAPER_INTERVAL_IDLE_MINS:-15}
      - SCRAPER_MAX_RETRIES=${SCRAPER_MAX_RETRIES:-3}
      - PROXY_ENABLED=${PROXY_ENABLED:-false}
      - PROXY_USERNAME=${PROXY_USERNAME}
      - PROXY_PASSWORD=${PROXY_PASSWORD}
      - PROXY_HOSTS=${PROXY_HOSTS}
      - NODE_ENV=production
    networks:
      - web
    restart: unless-stopped

  adsb-service:
    build:
      context: .
      dockerfile: apps/adsb-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - ADSB_INTERVAL_MS=${ADSB_INTERVAL_MS:-60000}
      - NODE_ENV=production
    networks:
      - web
    restart: unless-stopped

  guernsey-live:
    build:
      context: .
      dockerfile: apps/guernsey-scraper/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - SCRAPER_MODE=live
      - SCRAPER_CUTOFF_HOUR=${SCRAPER_CUTOFF_HOUR:-23}
      - SCRAPER_WAKE_OFFSET_MINS=${SCRAPER_WAKE_OFFSET_MINS:-30}
      - SCRAPER_INTERVAL_HIGH_MINS=${SCRAPER_INTERVAL_HIGH_MINS:-2}
      - SCRAPER_INTERVAL_MEDIUM_MINS=${SCRAPER_INTERVAL_MEDIUM_MINS:-5}
      - SCRAPER_INTERVAL_LOW_MINS=${SCRAPER_INTERVAL_LOW_MINS:-10}
      - SCRAPER_INTERVAL_IDLE_MINS=${SCRAPER_INTERVAL_IDLE_MINS:-15}
      - SCRAPER_INTERVAL_TOMORROW_MINS=${SCRAPER_INTERVAL_TOMORROW_MINS:-360}
      - GUERNSEY_AIRPORT_URL=${GUERNSEY_AIRPORT_URL:-https://www.airport.gg}
      - GUERNSEY_API_KEY=${GUERNSEY_API_KEY:?GUERNSEY_API_KEY is required}
      - NODE_ENV=production
    networks:
      - web
    restart: unless-stopped

  guernsey-backfill:
    build:
      context: .
      dockerfile: apps/guernsey-scraper/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - SCRAPER_MODE=backfill
      - BACKFILL_START_DATE=${BACKFILL_START_DATE:-2019-01-01}
      - BACKFILL_END_DATE=${BACKFILL_END_DATE}
      - GUERNSEY_AIRPORT_URL=${GUERNSEY_AIRPORT_URL:-https://www.airport.gg}
      - NODE_ENV=production
    networks:
      - web
    restart: on-failure
    profiles:
      - backfill

  position-service:
    build:
      context: .
      dockerfile: apps/position-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - FR24_API_TOKEN=${FR24_API_TOKEN}
      - POSITION_INTERVAL_MS=${POSITION_INTERVAL_MS:-300000}
      - NODE_ENV=production
    networks:
      - web
    restart: unless-stopped

  weather-service:
    build:
      context: .
      dockerfile: apps/weather-service/Dockerfile
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - OPENMETEO_API_URL=${OPENMETEO_API_URL:-https://api.open-meteo.com/v1/forecast}
      - NODE_ENV=production
    networks:
      - web
    restart: unless-stopped

  ml-service:
    build:
      context: apps/ml-service
      dockerfile: Dockerfile
    expose:
      - "8000"
    environment:
      - DATABASE_URL=${DATABASE_URL}
      - MODEL_PATH=/app/models
    volumes:
      - ml-models-dev:/app/models
    networks:
      - web
    restart: unless-stopped

networks:
  web:
    external: true

volumes:
  ml-models-dev:

